import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import * as HoverCardPrimitive from "@radix-ui/react-hover-card";
import { cn } from "@/lib/utils";

export const HoverCard = HoverCardPrimitive.Root;
export const HoverCardTrigger = HoverCardPrimitive.Trigger;
export const HoverCardPortal = HoverCardPrimitive.Portal;

export interface HoverCardContentProps
  extends React.ComponentPropsWithoutRef<typeof HoverCardPrimitive.Content> {
  width?: "auto" | "sm" | "md" | "lg";
}

const widthClasses: Record<NonNullable<HoverCardContentProps["width"]>, string> = {
  auto: "w-auto min-w-[12rem]",
  sm: "w-[14rem]",
  md: "w-[18rem]",
  lg: "w-[22rem]",
};

const hoverCardSurfaceClass =
  "border border-[#ded3c5] bg-[#f7f2e9] text-[#181716] " +
  "[box-shadow:0_26px_72px_-34px_rgba(0,0,0,.78),0_12px_34px_-20px_rgba(18,16,13,.46),0_1px_2px_rgba(18,16,13,.10)]";

const hoverCardTokenClass =
  "[--background:#fffaf2] [--foreground:#181716] [--muted-foreground:#655d52] [--border:#d8cab8] [--surface:#fffaf2]";

export function HoverCardContent({
  className,
  width = "auto",
  align = "center",
  sideOffset = 6,
  collisionPadding = 12,
  ...props
}: HoverCardContentProps) {
  return (
    <HoverCardPrimitive.Portal>
      <HoverCardPrimitive.Content
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "z-[120] origin-[var(--radix-hover-card-content-transform-origin)] transform-gpu outline-none",
          hoverCardSurfaceClass,
          hoverCardTokenClass,
          "rounded-[18px] p-4",
          "data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          "data-[state=open]:data-[side=bottom]:slide-in-from-top-2 data-[state=open]:data-[side=top]:slide-in-from-bottom-2",
          "data-[state=open]:data-[side=left]:slide-in-from-right-2 data-[state=open]:data-[side=right]:slide-in-from-left-2",
          "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          "data-[state=open]:duration-180 data-[state=closed]:duration-120",
          "data-[state=open]:ease-[cubic-bezier(0.23,1,0.32,1)] data-[state=closed]:ease-[cubic-bezier(0.23,1,0.32,1)]",
          "motion-reduce:animate-none",
          widthClasses[width],
          className,
        )}
        {...props}
      />
    </HoverCardPrimitive.Portal>
  );
}

export function HoverCardHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "border-b border-[#e4dbcf] pb-3 mb-3",
        className,
      )}
      {...props}
    />
  );
}

export function HoverCardBody({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("", className)} {...props} />;
}

export function HoverCardFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "border-t border-[#e4dbcf] pt-3 mt-3 flex items-center justify-end gap-2",
        className,
      )}
      {...props}
    />
  );
}

export function HoverCardTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn(
        "text-sm font-semibold tracking-[-0.01em] text-[#181716]",
        className,
      )}
      {...props}
    />
  );
}

export function HoverCardDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn(
        "mt-1 text-[12px] leading-[1.5] text-[#655d52]",
        className,
      )}
      {...props}
    />
  );
}
